 long defaultTime(){ArrayList<Task> tasks=Store.all(this);ArrayList<Integer> used=new ArrayList<>();for(Task t:tasks)if(t.active&&t.reminder){Calendar c=Calendar.getInstance();c.setTimeInMillis(t.anchor);used.add(c.get(Calendar.HOUR_OF_DAY)*60+c.get(Calendar.MINUTE));}int[] minutes=new int[used.size()];for(int i=0;i<used.size();i++)minutes[i]=used.get(i);return ReminderDefaults.nextWeekday(System.currentTimeMillis(),minutes);}
 void refreshTime(){if(dateButton==null||timeButton==null)return;dateButton.setText(new SimpleDateFormat("dd.MM.yyyy",Locale.GERMAN).format(new Date(chosen)));timeButton.setText(new SimpleDateFormat("HH:mm",Locale.GERMAN).format(new Date(chosen)));dateButton.setContentDescription(L.tr(this,"Datum auswählen"));timeButton.setContentDescription(L.tr(this,"Uhrzeit auswählen"));}
