 void parse(){String s=raw.getText().toString().trim();if(s.isEmpty()){toast(L.tr(this,"Du kannst die Aufgabe auch ohne Eingaben speichern."));return;}try{AlarmRules.Command command=AlarmRules.command(s);if(command.mode>=0){alarmMode.setSelection(command.mode);raw.setText(command.text);}TextParser.Result r=TextParser.parse(command.text,System.currentTimeMillis(),L.english(this));if(r.hasTime||r.hasRhythm||r.hasDate)reminder.setChecked(true);title.setText(r.title);if(r.hasTime||r.hasDate){chosen=ReminderDefaults.applyParsedTime(chosen,r.when,r.hasTime,r.hasDate,r.hasRhythm);refreshTime();}if(r.hasRhythm){rhythm.setSelection(r.kind);step.setText(String.valueOf(r.step));for(int i=0;i<7;i++)days[i].setChecked((r.mask&(1<<i))!=0);}else if(r.hasTime||r.hasDate)rhythm.setSelection(0);if(r.hasPause)pause.setText(String.valueOf(r.pause));if(r.hasIgnore)ignore.setSelection(r.ignore);toast(r.hasTime?L.tr(this,"Erkannt. Bitte Aufgabe und Regeln prüfen."):L.tr(this,"Als Aufgabe übernommen. Ein Termin ist optional."));}catch(Exception e){toast(L.tr(this,"Bitte den Termin und Rhythmus manuell festlegen."));}}
 void save(){if(title.getText().toString().trim().isEmpty()&&!raw.getText().toString().trim().isEmpty())parse();String text=DraftDefaults.title(title.getText().toString(),raw.getText().toString(),note.getText().toString());if(L.english(this)&&title.getText().toString().trim().isEmpty()&&raw.getText().toString().trim().isEmpty()&&note.getText().toString().trim().isEmpty())text="New task";int n=DraftDefaults.number(step.getText().toString(),1,525600),p=DraftDefaults.number(pause.getText().toString(),15,10080);int mask=0;for(int i=0;i<7;i++)if(days[i].isChecked())mask|=1<<i;if(mask==0)mask=31;int k=rhythm.getSelectedItemPosition();boolean enabled=reminder.isChecked();long now=System.currentTimeMillis();if(!enabled)k=0;if(k==0&&chosen<=now){Calendar nextDay=Calendar.getInstance();nextDay.setTimeInMillis(chosen);nextDay.add(Calendar.DAY_OF_MONTH,1);chosen=nextDay.getTimeInMillis();}
  if(enabled&&k==4){Calendar cal=Calendar.getInstance();cal.setTimeInMillis(chosen);while((mask&(1<<((cal.get(Calendar.DAY_OF_WEEK)+5)%7)))==0)cal.add(Calendar.DAY_OF_MONTH,1);chosen=cal.getTimeInMillis();}
  boolean editing=editingTaskId>=0;Task t;if(editing){t=Store.get(this,editingTaskId);if(t==null){toast(L.tr(this,"Aufgabe nicht mehr vorhanden"));backAfterSave();return;}}else{t=new Task();t.id=Store.newId(this);}boolean wasActive=editing&&t.active;long previousCompletion=editing?t.completedAt:0;t.title=text;t.note=note.getText().toString().trim();t.anchor=chosen;t.kind=k;t.step=n;t.mask=mask;t.ignore=k==0?0:ignore.getSelectedItemPosition();t.pause=p;t.doneMode=done.getSelectedItemPosition();t.alarmMode=alarmMode.getSelectedItemPosition();t.category=category.getSelectedItemPosition();t.reminder=enabled;t.active=editing?wasActive:true;t.next=enabled&&t.active?t.regular(now):0;t.last=0;t.completedAt=t.active?0:previousCompletion;Scheduler.clearNotification(this,t.id);Store.save(this,t);if(t.active)Scheduler.schedule(this,t);else Scheduler.cancel(this,t.id);Store.log(this,L.tr(this,"Aufgabe gespeichert: #")+t.id+(enabled?L.tr(this," · mit Erinnerung"):L.tr(this," · ohne Erinnerung")));boolean wasEnabled=enabled&&t.active;if(editing)backAfterSave();else{completed=false;home();}if(wasEnabled&&!Scheduler.exact(this))new AlertDialog.Builder(this).setTitle(L.tr(this,"Genaue Erinnerungszeiten aktivieren")).setMessage(L.tr(this,"Die Aufgabe ist gespeichert. Erlaube Alarme und Erinnerungen, damit TaskLoop zum eingestellten Zeitpunkt auslösen kann.")).setPositiveButton(L.tr(this,"Freigeben"),(d,w)->openExact()).setNegativeButton(L.tr(this,"Später"),null).show();else toast(wasEnabled?L.tr(this,"Gespeichert · ")+format(t.next):L.tr(this,"Gespeichert · ohne Erinnerung"));}
